import{_ as e,o,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"两个面试题项目：从面试现场到可交付的工程系统","description":"","frontmatter":{"title":"两个面试题项目：从面试现场到可交付的工程系统","date":"2026-09-29T00:00:00.000Z","tags":["项目复盘","FastAPI","Agent","工程实践"]},"headers":[],"relativePath":"posts/projects-overview.md","filePath":"posts/projects-overview.md","lastUpdated":1790688655000}'),i={name:"posts/projects-overview.md"};function l(s,t,n,u,p,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="两个面试题项目-从面试现场到可交付的工程系统" tabindex="-1">两个面试题项目：从面试现场到可交付的工程系统 <a class="header-anchor" href="#两个面试题项目-从面试现场到可交付的工程系统" aria-label="Permalink to &quot;两个面试题项目：从面试现场到可交付的工程系统&quot;">​</a></h1><p>面试官留了两道题，我做了两个能真实跑起来的系统：一个抖音数据监控工具，一个推广申请处理 Agent。这轮把它们从&quot;能跑&quot;工程化到&quot;能交付&quot;——SQLite、并行、upsert、幂等、Docker、CI、评测，全部落地。</p><h2 id="项目一-抖音数据监控工具" tabindex="-1">项目一：抖音数据监控工具 <a class="header-anchor" href="#项目一-抖音数据监控工具" aria-label="Permalink to &quot;项目一：抖音数据监控工具&quot;">​</a></h2><p><strong>解决什么问题</strong>：运营要看一批抖音账号的涨粉、获赞、视频数据，人工一个个打开网页看太慢，还容易漏。</p><p><strong>系统形态</strong>：Web 仪表盘 + 定时任务。</p><ul><li>采集层：Playwright 带登录态访问，多账号并行（线程池上限 3 防风控），账号级失败自动重试</li><li>存储层：SQLite（WAL），scan_history / alerts 双表，从旧 JSON 真实迁移 419 条历史 + 143 条告警</li><li>集成层：飞书表格 upsert（video_id → 行号映射，脏数据正则过滤），告警推飞书群</li><li>工程化：启动自检、Docker、GitHub Actions CI，38 项单测</li></ul><p><strong>核心链路</strong>：定时触发 → 并行采集 → 增量计算 → 超阈值告警 → 飞书同步 → 仪表盘展示。</p><h2 id="项目二-推广申请处理-agent" tabindex="-1">项目二：推广申请处理 Agent <a class="header-anchor" href="#项目二-推广申请处理-agent" aria-label="Permalink to &quot;项目二：推广申请处理 Agent&quot;">​</a></h2><p><strong>解决什么问题</strong>：运营每天在群里发推广申请（抖加 / 垫付），人工录入多维表格易错、难对账。</p><p><strong>系统形态</strong>：飞书群机器人，Master-Sub Agent 架构。</p><ul><li>提取：规则正则优先 + LLM 兜底（口语化文本），字段名容错映射兼容模型输出漂移</li><li>校验：金额/笔数一致性、日期逻辑、抖加档位、笔误（编辑距离 ≤ 2）、重复申请，8 项规则</li><li>确认：模板确认卡片 + 修改意见闭环，入库前人工确认</li><li>幂等：MD5 指纹三态流转，重复消息不重复处理、不重复调 LLM</li><li>评测：基于真实确认记录双模式 P/R/F1 100%（见《准确率 100% 不是玄学》）</li></ul><h2 id="为什么面试题值得做成这样" tabindex="-1">为什么面试题值得做成这样 <a class="header-anchor" href="#为什么面试题值得做成这样" aria-label="Permalink to &quot;为什么面试题值得做成这样&quot;">​</a></h2><p>面试题通常只要求&quot;能跑&quot;。往上走一步，它就从&quot;作业&quot;变成&quot;作品&quot;：</p><ul><li><strong>可验证</strong>：38 + 26 项单测，改坏了立刻知道</li><li><strong>可交付</strong>：Docker 一键起，别人 clone 下来 5 分钟跑起来</li><li><strong>可讲述</strong>：每个设计都有理由——为什么 SQLite、为什么规则优先、为什么人工确认</li></ul><blockquote><p>面试可展开：把两道题工程化 = 展示的不只是&quot;会写代码&quot;，而是&quot;知道一个真实系统要长什么样&quot;。</p></blockquote>',15)])])}const h=e(i,[["render",l]]);export{g as __pageData,h as default};
